pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address buyer, uint256 amount) public {
        vm.assume(buyer != address(0));
        amount = bound(amount, 0, 1 ether);

        uint256 TICKET = 10;

        vm.deal(buyer, 1 ether);

        if (amount == TICKET) {
            bool ok;
            vm.prank(buyer);
            try c.play{value: amount}() {
                ok = true;
            } catch {
                ok = false;
            }

            uint256 potAfter = c.pot();

            assertTrue(ok && potAfter >= TICKET);
        } else {
            assertTrue(true);
        }
    }
}
